package database

import models.Collections
import models.Rarities
import models.SkinPrices
import models.Skins
import models.Weapons
import models.WearConditions
import org.jetbrains.exposed.sql.SqlExpressionBuilder.eq
import org.jetbrains.exposed.sql.and
import org.jetbrains.exposed.sql.insert
import org.jetbrains.exposed.sql.select
import org.jetbrains.exposed.sql.selectAll
import org.jetbrains.exposed.sql.transactions.transaction
import org.jetbrains.exposed.sql.update
import java.math.BigDecimal

object SkinRepo {

    // Insert a new skin (IDs are Strings per schema)
    fun insertSkin(dto: InsertSkinDto): String {
        transaction {
            Skins.insert {
                it[Skins.skinId] = dto.skinId
                it[Skins.collectionId] = dto.collectionId
                it[Skins.name] = dto.name
                it[Skins.weaponId] = dto.weaponId
                it[Skins.patternId] = dto.patternId?.toString()
                it[Skins.patternName] = dto.patternName
                it[Skins.minFloat] = dto.minFloat?.toFloat()
                it[Skins.maxFloat] = dto.maxFloat?.toFloat()
                it[Skins.rarityId] = dto.rarityId
                it[Skins.stattrak] = dto.stattrak
                it[Skins.image] = dto.imageUrl
            }
        }
        return dto.skinId
    }

    // Get all skins with their collection, weapon, and rarity info
    fun getAllSkinsWithDetails(): List<SkinWithDetails> = transaction {
        (Skins leftJoin Collections leftJoin Weapons leftJoin Rarities)
            .selectAll()
            .map { row ->
                SkinWithDetails(
                    skinId = row[Skins.skinId],
                    skinName = row[Skins.name],
                    weaponName = row.getOrNull(Weapons.name),
                    collectionName = row.getOrNull(Collections.name),
                    rarityName = row.getOrNull(Rarities.name),
                    rarityColor = row.getOrNull(Rarities.colorHex),
                    minFloat = row[Skins.minFloat],
                    maxFloat = row[Skins.maxFloat],
                    stattrak = row[Skins.stattrak],
                    imageUrl = row[Skins.image]
                )
            }
    }

    // Get skin prices for a specific skin
    fun getSkinPrices(skinId: String): List<PriceInfo> = transaction {
        (SkinPrices innerJoin WearConditions)
            .selectAll()
            .where { SkinPrices.skinId eq skinId }
            .map { row ->
                PriceInfo(
                    wearCondition = row[WearConditions.name],
                    price         = row[SkinPrices.price],
                    quantity      = row[SkinPrices.quantity]
                )
            }
    }

    // Search skins by name
    fun searchSkinsByName(searchTerm: String): List<String> = transaction {
        Skins
            .selectAll()
            .where { Skins.name like "%$searchTerm%" }
            .map { it[Skins.name] }
    }

    // Get all StatTrak skins
    fun getStatTrakSkins(): List<String> = transaction {
        Skins
            .selectAll()
            .where { Skins.stattrak eq true }
            .map { it[Skins.name] }
    }

    // Get all skins of one Collection
    fun getSkinsByCollection(collectionId: String): List<String> = transaction {
        Skins
            .selectAll()
            .where { Skins.collectionId eq collectionId }
            .map { it[Skins.name] }
    }

    // Update skin price
    fun updateSkinPrice(skinId: String, wearId: String, newPrice: BigDecimal, quantity: Int) = transaction {
        val updated = SkinPrices.update({
            (SkinPrices.skinId eq skinId) and (SkinPrices.wearId eq wearId)
        }) {
            it[SkinPrices.price] = newPrice
            it[SkinPrices.quantity] = quantity
        }
        if (updated == 0) {
            SkinPrices.insert {
                it[SkinPrices.skinId] = skinId
                it[SkinPrices.wearId] = wearId
                it[SkinPrices.price] = newPrice
                it[SkinPrices.quantity] = quantity
            }
        }
    }

    // Get skins by rarity
    fun getSkinsByRarity(rarityName: String): List<String> = transaction {
        (Skins innerJoin Rarities)
            .selectAll()
            .where { Rarities.name eq rarityName }
            .map { it[Skins.name] }
    }
}

// Data classes for query results

data class SkinWithDetails(
    val skinId: String,
    val skinName: String,
    val weaponName: String?,
    val collectionName: String?,
    val rarityName: String?,
    val rarityColor: String?,
    val minFloat: Float?,
    val maxFloat: Float?,
    val stattrak: Boolean,
    val imageUrl: String?
)

// DTOs

data class InsertSkinDto(
    val skinId: String,
    val collectionId: String?,
    val name: String,
    val weaponId: String? = null,
    val patternId: Int? = null,
    val patternName: String? = null,
    val minFloat: Double? = null,
    val maxFloat: Double? = null,
    val rarityId: String? = null,
    val stattrak: Boolean = false,
    val imageUrl: String? = null
)


data class PriceInfo(
    val wearCondition: String,
    val price: BigDecimal,
    val quantity: Int
)

